package changelog

import (
	"sort"

	"github.com/stricttools/rlsbl/internal/git"
	"github.com/stricttools/rlsbl/internal/workspace"
)

// Exemption is why a commit needs no changelog entry, or empty when it
// needs one.
type Exemption string

// The exemptions, asked in this order: a commit both autogenerated and
// changelog-only is counted as autogenerated.
const (
	// ExemptAutogenerated: the commit carries the Autogenerated: true
	// trailer (machine-made: a release commit, a regenerated file).
	ExemptAutogenerated Exemption = "autogenerated"
	// ExemptChangelogOnly: every file the commit changes is tool-owned,
	// rlsbl's own bookkeeping (the changelog, the release records).
	ExemptChangelogOnly Exemption = "changelog-only"
)

// ExemptionOf is why commit sha needs no entry, or empty when it needs
// one. A commit git cannot read is an error: whether it needs an entry
// cannot be guessed.
func ExemptionOf(repo git.Repo, sha string) (Exemption, error) {
	auto, err := repo.IsAutogenerated(sha)
	if err != nil {
		return "", err
	}
	if auto {
		return ExemptAutogenerated, nil
	}
	files, err := repo.CommitFiles(sha)
	if err != nil {
		return "", err
	}
	if len(files) == 0 {
		return "", nil
	}
	for _, f := range files {
		if !workspace.IsToolOwned(f) {
			return "", nil
		}
	}
	return ExemptChangelogOnly, nil
}

// ExemptionStats count the commits each exemption took out.
type ExemptionStats struct {
	Autogenerated int
	ChangelogOnly int
}

// FilterExempt keeps the commits, in their order, that need an entry.
func FilterExempt(repo git.Repo, commits []string) ([]string, ExemptionStats, error) {
	var stats ExemptionStats
	var kept []string
	for _, sha := range commits {
		why, err := ExemptionOf(repo, sha)
		if err != nil {
			return nil, ExemptionStats{}, err
		}
		switch why {
		case ExemptAutogenerated:
			stats.Autogenerated++
		case ExemptChangelogOnly:
			stats.ChangelogOnly++
		default:
			kept = append(kept, sha)
		}
	}
	return kept, stats, nil
}

// Needing is what CommitsNeedingEntries found.
type Needing struct {
	// Commits need an entry, sorted.
	Commits []string
	Stats   ExemptionStats
	// OutsideScope counts the commits that touch nothing the scope claims.
	OutsideScope int
}

// CommitsNeedingEntries are the commits of commits that changelog coverage
// asks an entry for, in its order: keep the commits touching a file the
// scope claims, drop the ones covered already names (full ids), then drop
// the exempt ones. Coverage answers through it, and so does a command
// asking whether a commit it just made needs an entry.
func CommitsNeedingEntries(repo git.Repo, commits []string, scope workspace.Scope, covered map[string]bool) (Needing, error) {
	unique := dedupe(commits)
	inScope, err := workspace.FilterCommits(repo, unique, scope)
	if err != nil {
		return Needing{}, err
	}
	var uncovered []string
	for _, c := range inScope {
		if !covered[c] {
			uncovered = append(uncovered, c)
		}
	}
	sort.Strings(uncovered)
	needing, stats, err := FilterExempt(repo, uncovered)
	if err != nil {
		return Needing{}, err
	}
	return Needing{Commits: needing, Stats: stats, OutsideScope: len(unique) - len(inScope)}, nil
}

func dedupe(values []string) []string {
	seen := map[string]bool{}
	var out []string
	for _, v := range values {
		if !seen[v] {
			seen[v] = true
			out = append(out, v)
		}
	}
	return out
}
